  DROP VIEW public.v_rt_segments;
  DROP TABLE public.rt_vehicle_segments;
  FOREACH v_f IN ARRAY ARRAY['public.plan_seg_change(jsonb,text,text)',
      'public.plan_seg_fix(jsonb,text,text)',
      'public.plan_seg_remove(jsonb,text,text)',
      'public.plan_h_seg_busy(bigint)',
      'public.plan_h_seg_set_only(bigint,text,bigint,bigint,bigint,bigint,numeric,text,text)',
      'public.plan_h_seg_clear(bigint,text,text,text)',
      'public.plan_h_seg_json(bigint)',
      'public.plan_h_vs_carriers(bigint,jsonb)',
      'public.plan_h_seg_of_stop(bigint)',
      'public.plan_h_seg_stops(bigint)',
      'public.plan_h_seg_stop_warn(bigint,jsonb)',
      'public.plan_h_seg_v1_warn(bigint)',
      'public.plan_h_seg_next_rt(bigint)',
      'public.plan_h_seg_vehicle_ok(text,bigint,bigint,bigint,bigint,numeric)',
      'public.plan_h_seg_consequences(bigint[])',
      'public.plan_h_seg_drop(bigint,bigint[],bigint[],text,text,text)',
      'public.plan_h_seg_cut_list(bigint,timestamptz,timestamptz)',
      'public.plan_h_seg_cut_legs(bigint[],bigint)',
      'public.plan_h_seg_cut_keep(bigint[],bigint,jsonb)',
      'public.plan_h_seg_rt_cut(bigint,bigint[],timestamptz[],timestamptz[],text,interval)',
      'public.plan_h_seg_cut(jsonb,text,text,text)',
      'public.plan_seg_problem(bigint)',
      'public.plan_chk_seg()',
      'public.plan_seg_follow()',
      'public.plan_seg_copy()'] LOOP
    EXECUTE format('DROP FUNCTION %s', v_f);
  END LOOP;

  -- 3. the two EXCLUDE of 071b back on the cycles, with 071b's own words
  ALTER TABLE public.ct_round_trips
    ADD CONSTRAINT rt_v2_truck_once EXCLUDE USING gist (truck_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&)
      WHERE (model = 2 AND trip_type = 'OWNED' AND truck_id IS NOT NULL AND status <> 'cancelled')
      DEFERRABLE INITIALLY DEFERRED,
    ADD CONSTRAINT rt_v2_driver_once EXCLUDE USING gist (driver_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&)
      WHERE (model = 2 AND trip_type = 'OWNED' AND driver_id IS NOT NULL AND status <> 'cancelled')
      DEFERRABLE INITIALLY DEFERRED;

  -- PROOFS
  IF v_n <> 16 THEN RAISE EXCEPTION '072b rollback proof: % hooks out (expected 16)', v_n; END IF;
  IF (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.ct_round_trips'::regclass
       AND conname = 'rt_v2_truck_once') IS DISTINCT FROM x_truck
     OR (SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'public.ct_round_trips'::regclass
       AND conname = 'rt_v2_driver_once') IS DISTINCT FROM x_driver THEN
    RAISE EXCEPTION '072b rollback proof: the EXCLUDE on ct_round_trips are not 071b''s';
  END IF;
  IF (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname LIKE 'plan\_%') <> 54 THEN
    RAISE EXCEPTION '072b rollback proof: plan_* count is not the 54 of 071 + 072';
  END IF;
  SELECT count(*) INTO v_trg1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
    JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF v_trg1 <> v_trg0 - 4 THEN
    RAISE EXCEPTION '072b rollback proof: trigger count % -> % (expected -4)', v_trg0, v_trg1;
  END IF;
  UPDATE monitoring.checks SET red_value = v_trg1 WHERE id = 'B-54' AND red_value = v_trg0;
  GET DIAGNOSTICS v_k = ROW_COUNT;
  IF v_k <> 1 THEN RAISE EXCEPTION '072b rollback: B-54 not updated (% rows)', v_k; END IF;
  PERFORM pg_notify('pgrst', 'reload schema');
  RAISE NOTICE '072b ROLLBACK OK: 16 hooks out, segments gone, the EXCLUDE of 071b back on the cycles; triggers % -> %', v_trg0, v_trg1;
END $do$;

SELECT CASE WHEN to_regclass('public.rt_vehicle_segments') IS NULL THEN '072b ROLLED BACK' ELSE '072b STILL IN PLACE' END AS result,
       (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.ct_round_trips'::regclass AND contype = 'x') AS exclude_on_cycles,
       (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname LIKE 'plan\_seg\_%') AS seg_functions,
       (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname LIKE 'plan\_%') AS plan_functions,
       (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
         WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public') AS public_triggers,
       (SELECT red_value FROM monitoring.checks WHERE id = 'B-54') AS b54_red_value;
